input.query:
with ep as (select sum(p.written_premium * greatest(0, date_diff('day', greatest(p.effective_date, date '2024-01-01'), least(p.cover_end_date, date '2025-01-01'))) / nullif(date_diff('day', p.effective_date, p.cover_end_date),0)) e from premium_txn p join policy_term t using(term_id) where t.region='LONDON'),
inc as (select sum(x.amount) i, sum(case when x.txn_type='RESERVE' then x.amount end) os from claim c join claim_txn x using(claim_id) join policy_term t on t.term_id=c.term_id where t.region='LONDON' and year(c.accident_date)=2024 and x.txn_date<=date '2025-12-31')
select e,i,os,i/e from ep, inc;
